def patch_database():
    with open(DB_PATH, 'r', encoding='utf-8') as f:
        db = json.load(f)

    concepts = db['concepts']

    # Remove duplicate concept entries (keep lowest-id version)
    seen_names = {}
    deduped = []
    removed = []
    for c in concepts:
        name = c['name'].strip()
        if name in seen_names:
            removed.append((c['id'], name))
        else:
            seen_names[name] = c['id']
            deduped.append(c)

    if removed:
        print(f"Removing {len(removed)} duplicate concepts:")
        for dup_id, dup_name in removed:
            print(f"  id={dup_id} '{dup_name}'")

    db['concepts'] = deduped

    # Apply enriched entries
    patched = 0
    for c in db['concepts']:
        cid = c['id']
        if cid in ENRICHED_CONCEPTS:
            patch = ENRICHED_CONCEPTS[cid]
            c.update(patch)
            patched += 1
            print(f"  Enriched: [{cid}] {c['name']} ({len(c['essay'].split())} words)")

    with open(DB_PATH, 'w', encoding='utf-8') as f:
        json.dump(db, f, ensure_ascii=False, indent=2)

    print(f"\nDone. Enriched {patched} concepts, removed {len(removed)} duplicates.")
    print(f"Concept count: {len(deduped)} (was {len(concepts)})")


if __name__ == "__main__":
    patch_database()
